import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Stage 1: many blocks per row. Each block reduces one contiguous chunk
// of a row into a partial sum and partial sum-of-squares. The grid has
// rows * nchunks blocks so every SM is utilized even for few rows.
__global__ void layernorm_partial_kernel(const float* __restrict__ x,
                                         float* __restrict__ p_sum,
                                         float* __restrict__ p_sq,
                                         int64_t N,
                                         int64_t chunk,
                                         int64_t nchunks,
                                         int64_t total) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats
    // Grid-stride loop: each persistent block processes several
    // (row, chunk) pairs so the grid can be sized to fill every SM.
    for (int64_t blk = blockIdx.x; blk < total; blk += gridDim.x) {
        const int64_t row   = blk / nchunks;
        const int64_t c     = blk % nchunks;
        const int64_t start = c * chunk;
        int64_t end = start + chunk;
        if (end > N) end = N;
        const float* __restrict__ xr = x + row * N;
        float sum = 0.0f;
        float sq  = 0.0f;
        for (int64_t i = start + threadIdx.x; i < end; i += blockDim.x) {
            float v = xr[i];
            sum += v;
            sq  += v * v;
        }
        s_sum[threadIdx.x] = sum;
        s_sq[threadIdx.x]  = sq;
        __syncthreads();
        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
            if (threadIdx.x < s) {
                s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
                s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
            }
            __syncthreads();
        }
        if (threadIdx.x == 0) {
            p_sum[blk] = s_sum[0];
            p_sq[blk]  = s_sq[0];
        }
        __syncthreads();
