// Fused single-kernel LayerNorm: one block per row. The head of each
// row is staged in shared memory while its statistics are accumulated,
// so the normalize phase re-reads only the unstaged tail from DRAM.
// This reduces global-memory traffic for this DRAM-bound workload.
__global__ void layernorm_fused_smem_kernel(const float4* __restrict__ x,
                                            const float4* __restrict__ w,
                                            const float4* __restrict__ b,
                                            float4* __restrict__ y,
                                            int64_t N,
                                            int64_t N4,
                                            int64_t rows,
                                            int64_t stage4,
                                            float eps) {
    extern __shared__ float4 s_data[];  // stage4 float4 staged head of the row
    __shared__ float s_warp_sum[32];
    __shared__ float s_warp_sq[32];
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int nwarps = nthr >> 5;
    for (int64_t row = blockIdx.x; row < rows; row += gridDim.x) {
        const float4* __restrict__ xr = x + row * N4;
        float4* __restrict__ yr = y + row * N4;
        float sum = 0.0f;
        float sq  = 0.0f;
        // Pass 1: stream the row once. The first stage4 vectors are kept
        // in shared memory for the normalize phase; the tail is consumed
        // on the fly.
        for (int64_t i = tid; i < N4; i += nthr) {
            float4 v = xr[i];
            if (i < stage4) s_data[i] = v;
            sum += v.x + v.y + v.z + v.w;
            sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        }
        // Warp-shuffle reduction (uses no extra staged shared memory).
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            sum += __shfl_down_sync(0xffffffffu, sum, off);
            sq  += __shfl_down_sync(0xffffffffu, sq, off);
        }
        if (lane == 0) {
            s_warp_sum[warp] = sum;
            s_warp_sq[warp]  = sq;
        }
        __syncthreads();
        if (warp == 0) {
            float tsum = (lane < nwarps) ? s_warp_sum[lane] : 0.0f;
            float tsq  = (lane < nwarps) ? s_warp_sq[lane]  : 0.0f;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1) {
                tsum += __shfl_down_sync(0xffffffffu, tsum, off);
                tsq  += __shfl_down_sync(0xffffffffu, tsq, off);
            }
            if (lane == 0) {
                const float mean = tsum / (float)N;
                float var = tsq / (float)N - mean * mean;
                var = var < 0.0f ? 0.0f : var;
                s_mean = mean;
                s_rstd = rsqrtf(var + eps);
            }
        }
        __syncthreads();
        const float mean = s_mean;
        const float rstd = s_rstd;
        // Pass 2a: normalize the staged head directly from shared memory.
        for (int64_t i = tid; i < stage4; i += nthr) {
            float4 xv = s_data[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        // Pass 2b: re-read only the unstaged tail from global memory.
        for (int64_t i = stage4 + tid; i < N4; i += nthr) {
            float4 xv = xr[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        __syncthreads();
    }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
