        const int64_t max_chunks = (N4 + threads - 1) / threads;
        if (chunks > max_chunks) chunks = max_chunks;
        if (chunks < 1) chunks = 1;
        const int64_t chunk = (N4 + chunks - 1) / chunks;
        chunks = (N4 + chunk - 1) / chunk;
        const int64_t total = rows * chunks;
