// row is staged in shared memory while its statistics are accumulated,
// so the normalize phase re-reads only the unstaged tail from DRAM.
// This reduces global-memory traffic for this DRAM-bound workload.
__global__ void layernorm_fused_smem_kernel(const float4* __restrict__ x,
                                            const float4* __restrict__ w,
                                            const float4* __restrict__ b,
                                            float4* __restrict__ y,
                                            int64_t N,
                                            int64_t N4,
                                            int64_t rows,
                                            int64_t stage4,
                                            float eps) {
    extern __shared__ float4 s_data[];  // stage4 float4 staged head of the row
    __shared__ float s_warp_sum[32];
    __shared__ float s_warp_sq[32];
    __shared__ float s_mean;
    __shared__ float s_rstd;
    const int tid = threadIdx.x;
    const int nthr = blockDim.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int nwarps = nthr >> 5;
    for (int64_t row = blockIdx.x; row < rows; row += gridDim.x) {
        const float4* __restrict__ xr = x + row * N4;
        float4* __restrict__ yr = y + row * N4;
        float sum = 0.0f;
        float sq  = 0.0f;
        // Pass 1: stream the row once. The first stage4 vectors are kept
        // in shared memory for the normalize phase; the tail is consumed
        // on the fly.
        for (int64_t i = tid; i < N4; i += nthr) {
            float4 v = xr[i];
            if (i < stage4) s_data[i] = v;
            sum += v.x + v.y + v.z + v.w;
            sq  += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        }
        // Warp-shuffle reduction (uses no extra staged shared memory).
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
            sum += __shfl_down_sync(0xffffffffu, sum, off);
            sq  += __shfl_down_sync(0xffffffffu, sq, off);
        }
        if (lane == 0) {
            s_warp_sum[warp] = sum;
            s_warp_sq[warp]  = sq;
        }
        __syncthreads();
        if (warp == 0) {
            float tsum = (lane < nwarps) ? s_warp_sum[lane] : 0.0f;
            float tsq  = (lane < nwarps) ? s_warp_sq[lane]  : 0.0f;
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1) {
                tsum += __shfl_down_sync(0xffffffffu, tsum, off);
                tsq  += __shfl_down_sync(0xffffffffu, tsq, off);
            }
            if (lane == 0) {
                const float mean = tsum / (float)N;
                float var = tsq / (float)N - mean * mean;
                var = var < 0.0f ? 0.0f : var;
                s_mean = mean;
                s_rstd = rsqrtf(var + eps);
            }
        }
        __syncthreads();
        const float mean = s_mean;
        const float rstd = s_rstd;
        // Pass 2a: normalize the staged head directly from shared memory.
        for (int64_t i = tid; i < stage4; i += nthr) {
            float4 xv = s_data[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        // Pass 2b: re-read only the unstaged tail from global memory.
        for (int64_t i = stage4 + tid; i < N4; i += nthr) {
            float4 xv = xr[i];
            float4 wv = w[i];
            float4 bv = b[i];
            float4 o;
            o.x = (xv.x - mean) * rstd * wv.x + bv.x;
            o.y = (xv.y - mean) * rstd * wv.y + bv.y;
            o.z = (xv.z - mean) * rstd * wv.z + bv.z;
            o.w = (xv.w - mean) * rstd * wv.w + bv.w;
            yr[i] = o;
        }
        __syncthreads();
    }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto y = torch::empty_like(x);
    const int64_t rows = x.numel() / normalized_size;
    const int64_t N = normalized_size;
    const int threads = 256;
    const int sms = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    const size_t shmem = 2 * threads * sizeof(float);
    auto stream = at::cuda::getCurrentCUDAStream();
    // Fused single-kernel path (the workload is DRAM bound and x is
    // otherwise read twice): one block per row stages the head of the
    // row in opt-in shared memory while accumulating sum/sum-of-squares,
    // then normalizes from shared memory, cutting global-memory traffic.
    if ((N & 3) == 0) {
        auto* fprop = at::cuda::getCurrentDeviceProperties();
        const int64_t N4f = N >> 2;
        int64_t target = ((int64_t)fprop->sharedMemPerMultiprocessor / 2) - 2048;
        if (target > (int64_t)fprop->sharedMemPerBlockOptin)
            target = (int64_t)fprop->sharedMemPerBlockOptin;
        target &= ~(int64_t)15;
        int64_t stage4 = target / (int64_t)sizeof(float4);
        if (stage4 > N4f) stage4 = N4f;
        if (stage4 >= 4096 && rows >= (int64_t)sms) {
            const int fthreads = 512;
            const size_t fsmem = (size_t)stage4 * sizeof(float4);
            cudaFuncSetAttribute(layernorm_fused_smem_kernel,
                                 cudaFuncAttributeMaxDynamicSharedMemorySize,
                                 (int)fsmem);
            int fblocks_per_sm = 0;
            cudaOccupancyMaxActiveBlocksPerMultiprocessor(
                &fblocks_per_sm, layernorm_fused_smem_kernel, fthreads, fsmem);
            if (fblocks_per_sm < 1) fblocks_per_sm = 1;
            int64_t fgrid = (int64_t)sms * fblocks_per_sm;
            if (fgrid > rows) fgrid = rows;
            layernorm_fused_smem_kernel<<<(unsigned int)fgrid, fthreads, fsmem, stream>>>(
                reinterpret_cast<const float4*>(x.data_ptr<float>()),
                reinterpret_cast<const float4*>(w.data_ptr<float>()),
                reinterpret_cast<const float4*>(b.data_ptr<float>()),
                reinterpret_cast<float4*>(y.data_ptr<float>()),
                N,
                N4f,
                rows,
                stage4,
                (float)eps);
            return y;
        }
    }
    if ((N & 3) == 0) {
        // Vectorized path. The grid is sized from the kernel's occupancy
        // (persistent grid-stride launch) so every SM stays fully occupied
        // and blocks loop over (row, chunk) pairs.
        const int64_t N4 = N >> 2;
        int blocks_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &blocks_per_sm, layernorm_partial_vec4_kernel, threads, shmem);
        if (blocks_per_sm < 1) blocks_per_sm = 1;
        const int64_t target_blocks = (int64_t)sms * blocks_per_sm;
        int64_t chunks = (target_blocks + rows - 1) / rows;
        const int64_t max_chunks = (N4 + threads - 1) / threads;
        if (chunks > max_chunks) chunks = max_chunks;
        if (chunks < 1) chunks = 1;
        const int64_t chunk = (N4 + chunks - 1) / chunks;
        chunks = (N4 + chunk - 1) / chunk;
        const int64_t total = rows * chunks;
        auto p_sum = torch::empty({total}, x.options());
        auto p_sq  = torch::empty({total}, x.options());
        int64_t grid_blocks = target_blocks < total ? target_blocks : total;
        const dim3 grid((unsigned int)grid_blocks);
        layernorm_partial_vec4_kernel<<<grid, threads, shmem, stream>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N4,
            chunk,
            chunks,
            total);
        layernorm_normalize_vec4_kernel<<<grid, threads, shmem, stream>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<const float4*>(w.data_ptr<float>()),
            reinterpret_cast<const float4*>(b.data_ptr<float>()),
            reinterpret_cast<float4*>(y.data_ptr<float>()),
            p_sum.data_ptr<float>(),
            p_sq.data_ptr<float>(),
            N,
            N4,
            chunk,
            chunks,
            total,
            (float)eps);
    } else {
        // Scalar fallback with the same persistent grid-stride launch.
        int blocks_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(
            &blocks_per_sm, layernorm_partial_kernel, threads, shmem);
        if (blocks_per_sm < 1) blocks_per_sm = 1;
